rows = 5
cols = 10

# Create mapping from (r,c) to index
cell_to_index = {}
for r in range(rows):
    for c in range(cols):
        idx = r * cols + c
        cell_to_index[(r,c)] = idx

# Find all X cells
all_x_cells = []
for r in range(rows):
    for c in range(cols):
        if grid[r][c] == 'X':
            idx = r * cols + c
            all_x_cells.append((r,c, idx))

print(f"all_x_cells length: {len(all_x_cells)}")

# Build adjacency list
adjacency = [[] for _ in range(len(all_x_cells))]

for idx in range(len(all_x_cells)):
    r, c, cell_idx = all_x_cells[idx]

    print(f"Processing cell at ({r},{c}) with index {cell_idx}")

    # Check 4 directions
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc

        print(f"Checking neighbor ({nr},{nc}) - index = {nr*cols + nc}, grid value = {grid[nr][nc]}")

        if 0 <= nr < rows and 0 <= nc < cols:
            if grid[nr][nc] == 'X':
                nr_cell_idx = nr * cols + nc
                adjacency[cell_idx].append(nr_cell_idx)
                print(f"Added neighbor: {nr_cell_idx}")
            else:
                print(f"Neighbor is NOT X (blocked)")
